<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { storeToRefs } from "pinia";
import { useRoute } from "vue-router";
import { Copy, Eye, Pencil, Plus, Power, RefreshCw, Search } from "@lucide/vue";
import StatePanel from "@/components/StatePanel.vue";
import { useMifcFormsStore } from "@/stores/mifc-forms";
import { useOperationsStore } from "@/stores/operations";
import type { MasterDataRecord, ProcessRecord, ProductRecord, ResourceRecord } from "@/domain/operations";

const props = defineProps<{ mode: "products"|"processes"|"resources"|"master" }>();
const route = useRoute();
const store = useOperationsStore();
const forms = useMifcFormsStore();
const { products, processes, resources, masterData, settings } = storeToRefs(store);
const loading = ref(true);
const error = ref("");
const success = ref("");
const search = ref("");
const statusFilter = ref("all");
const editorOpen = ref(false);
const detailsOpen = ref(false);
const routeProduct = ref<ProductRecord | null>(null);
const editing = ref<Record<string, any>>({});
const operational = ref<{values:Record<string,number>|null;updatedAt:string|null;ready:boolean}>({values:null,updatedAt:null,ready:false});
let operationalTimer:ReturnType<typeof setInterval>|undefined;

const title = computed(() => ({products:"Produtos",processes:"Processos",resources:"Máquinas & Recursos",master:"Dados mestre"}[props.mode]));
const description = computed(() => ({products:"Produto, cliente, família e rota em uma visão operacional legível.",processes:"Cadastro técnico, participação por cliente, medidas e estado de paridade.",resources:"Máquinas e recursos físicos com dados observados; planejamento permanece em Capacidade.",master:"Parâmetros estáveis, unidades, origem e estado dos cadastros."}[props.mode]));
const records = computed(() => props.mode==="products"?products.value:props.mode==="processes"?processes.value:props.mode==="resources"?resources.value:masterData.value);
const filtered = computed(() => records.value.filter((record) => {
  const text=JSON.stringify(record).toLocaleLowerCase("pt-BR");
  return (!search.value||text.includes(search.value.toLocaleLowerCase("pt-BR"))) && (statusFilter.value==="all"||record.status===statusFilter.value);
}));

function blank() {
  const updatedAt=new Date().toISOString();
  if(props.mode==="products") return {id:store.uid("product"),code:"",description:"",customer:"",family:"",productClass:"",hand:"",finishLength:undefined,material:"",status:"active",origin:"LOCAL",updatedAt,routeProcessIds:[],overrides:{}} satisfies ProductRecord;
  if(props.mode==="processes") return {id:store.uid("process"),code:"",name:"",sequence:processes.value.length*10+10,type:"",customerKeys:[],productIds:[],resourceIds:[],layoutNodeId:"",powerBiMeasure:"",demandMeasure:"",productionMeasure:"",status:"active",notes:"",validation:"pending",updatedAt} satisfies ProcessRecord;
  if(props.mode==="resources") return {id:store.uid("resource"),code:"",name:"",processId:"",availableHoursPerDay:0,availableMinutes:0,shifts:2,oeeTarget:85,operationalStatus:"unknown",status:"active",origin:"LOCAL",updatedAt} satisfies ResourceRecord;
  return {id:store.uid("master"),category:"",key:"",label:"",value:"",unit:"",origin:"LOCAL",status:"active",notes:"",updatedAt} satisfies MasterDataRecord;
}
function openEditor(record?: Record<string, unknown>){editing.value=structuredClone(record??blank());editorOpen.value=true;detailsOpen.value=false;}
function openDetails(record: Record<string, unknown>){editing.value=structuredClone(record);detailsOpen.value=true;editorOpen.value=false;}
function save(){
  if(props.mode==="products") {
    const product=editing.value as unknown as ProductRecord;
    const original=products.value.find((item)=>item.id===product.id);
    if(original?.origin==="ORACLE_MES") product.overrides={ code:product.code,description:product.description,customer:product.customer,family:product.family,productClass:product.productClass,hand:product.hand,finishLength:product.finishLength,material:product.material,status:product.status,routeProcessIds:[...product.routeProcessIds] };
    store.upsertProduct(product);
  }
  else if(props.mode==="processes") store.upsertProcess(editing.value as unknown as ProcessRecord);
  else if(props.mode==="resources"){const item=editing.value as unknown as ResourceRecord;item.availableMinutes=Number(item.availableHoursPerDay||0)*60;store.upsertResource(item);}
  else store.upsertMasterData(editing.value as unknown as MasterDataRecord);
  success.value="Registro salvo com sucesso na persistência local.";editorOpen.value=false;
}
function duplicate(id:string){if(props.mode==="products")store.duplicateProduct(id);else if(props.mode==="processes")store.duplicateProcess(id);else if(props.mode==="resources")store.duplicateResource(id);success.value="Cópia criada como registro local.";}
function toggle(id:string){store.toggle(props.mode==="products"?"product":props.mode==="processes"?"process":props.mode==="resources"?"resource":"master",id);}
function recordLabel(record: ProductRecord|ProcessRecord|ResourceRecord|MasterDataRecord){if(props.mode==="products")return(record as ProductRecord).description;if(props.mode==="processes")return(record as ProcessRecord).name;if(props.mode==="resources")return(record as ResourceRecord).name;return(record as MasterDataRecord).label;}
async function syncProducts(){error.value="";try{const count=await store.syncOracleProducts();success.value=count?`${count.toLocaleString("pt-BR")} produtos derivados do cache Oracle foram conciliados.`:"As tabelas ainda não possuem produtos carregados no cache local.";}catch(e){error.value=e instanceof Error?e.message:"Falha ao sincronizar produtos.";}}
function routeCount(ids:string[]){return `${ids.length} ${ids.length===1?'processo':'processos'}`;}
function customerNames(keys:string[]){return keys.length?keys.join(", "):"—";}
function measure(resource:ResourceRecord,key?:string){if(!key||!operational.value.values)return undefined;return operational.value.values[key];}
function validationLabel(validation:ProcessRecord["validation"]){return validation==="mapped"?"Validado":validation==="divergent"?"Divergente":"Pendente";}
function fmt(value:unknown,decimals=0){return typeof value==="number"&&Number.isFinite(value)?value.toLocaleString("pt-BR",{minimumFractionDigits:decimals,maximumFractionDigits:decimals}):"—";}
async function loadOperational(){try{const response=await fetch("/api/layout/measures",{cache:"no-store"});if(response.ok)operational.value=await response.json() as typeof operational.value;}catch{/* dados locais continuam disponíveis */}}
watch([search,statusFilter],()=>localStorage.setItem(`mifc-digital:prompt-7:filters:${props.mode}`,JSON.stringify({search:search.value,status:statusFilter.value})));
onMounted(async()=>{store.hydrate();forms.hydrate();const raw=localStorage.getItem(`mifc-digital:prompt-7:filters:${props.mode}`);if(raw){try{const saved=JSON.parse(raw);search.value=saved.search??"";statusFilter.value=saved.status??"all";}catch{/* ignora filtro inválido */}}store.syncCapacity(forms.capacityRows);await loadOperational();if(props.mode==="products")await syncProducts();if(props.mode==="resources")operationalTimer=setInterval(()=>void loadOperational(),Math.max(15,settings.value.refreshSeconds)*1000);const focus=typeof route.query.focus==="string"?records.value.find((item)=>item.id===route.query.focus):undefined;if(focus)openDetails(focus as unknown as Record<string,unknown>);loading.value=false;if(!success.value)success.value=`${records.value.length} registros disponíveis. Filtros e alterações locais são persistidos neste navegador.`;});
onBeforeUnmount(()=>{if(operationalTimer)clearInterval(operationalTimer);});
</script>

<template>
  <main class="page registry-page">
    <header class="page-heading"><div><p class="eyebrow">GESTÃO OPERACIONAL</p><h1>{{ title }}</h1><p>{{ description }}</p></div><div class="page-actions"><button v-if="mode==='products'" class="button button-secondary" @click="syncProducts"><RefreshCw :size="16"/>Sincronizar do Oracle</button><button class="button button-primary" @click="openEditor()"><Plus :size="16"/>Adicionar {{ mode==='products'?'produto':mode==='processes'?'processo':mode==='resources'?'máquina/recurso':'parâmetro' }}</button></div></header>
    <StatePanel v-if="loading" state="loading" />
    <template v-else>
      <div v-if="error" class="context-banner danger" role="alert">{{ error }}</div>
      <div v-else-if="success" class="context-banner success">{{ success }}</div>
      <section class="card filter-card"><div class="search-box"><Search :size="16"/><input v-model="search" :placeholder="`Pesquisar em ${title.toLocaleLowerCase('pt-BR')}...`"/></div><select v-model="statusFilter"><option value="all">Todos os status</option><option value="active">Ativos</option><option value="inactive">Inativos</option></select><span>{{ filtered.length }} de {{ records.length }}</span></section>
      <div v-if="mode==='processes'" class="parity-legend" aria-label="Estados de paridade"><span class="validation mapped">Validado</span><span class="validation divergent">Divergente</span><span class="validation pending">Pendente</span><small>Estado da regra e do vínculo com a fonte; não é o status ativo/inativo.</small></div>
      <StatePanel v-if="!filtered.length" state="empty" title="Nenhum registro encontrado" message="Altere os filtros ou adicione um novo registro." />
      <section v-else class="card table-card" :class="{compact:settings.compactTables}"><div class="table-scroll"><table class="data-table">
        <thead><tr v-if="mode==='products'"><th>Código / descrição</th><th>Cliente</th><th>Família / classe</th><th>Mão / comprimento</th><th>Material</th><th>Rota</th><th>Origem</th><th>Status</th><th>Ações</th></tr><tr v-else-if="mode==='processes'"><th>Seq.</th><th>Processo</th><th>Tipo</th><th>Clientes</th><th>Recursos</th><th>Nó Layout</th><th>Medidas</th><th>Paridade</th><th>Ações</th></tr><tr v-else-if="mode==='resources'"><th>Máquina / recurso</th><th>Processo</th><th>Estado do dado</th><th>Produção / demanda</th><th>Restante</th><th>Paradas / downtime</th><th>OEE-meta</th><th>Atualizado</th><th>Planejamento</th><th>Ações</th></tr><tr v-else><th>Categoria</th><th>Chave</th><th>Nome</th><th>Valor</th><th>Origem</th><th>Status</th><th>Atualizado</th><th>Ações</th></tr></thead>
        <tbody>
          <tr v-for="record in filtered" :key="record.id" :class="{ 'inactive-row': record.status === 'inactive' }">
            <template v-if="mode==='products'"><td><strong>{{ (record as ProductRecord).code }}</strong><small>{{ (record as ProductRecord).description }}</small></td><td>{{ (record as ProductRecord).customer||'—' }}</td><td>{{ (record as ProductRecord).family||'—' }}<small>{{ (record as ProductRecord).productClass||'—' }}</small></td><td>{{ (record as ProductRecord).hand||'—' }}<small>{{ fmt((record as ProductRecord).finishLength) }} mm</small></td><td>{{ (record as ProductRecord).material||'—' }}</td><td class="route-cell"><strong>{{ routeCount((record as ProductRecord).routeProcessIds) }}</strong><button class="route-button" @click="routeProduct=record as ProductRecord">Ver rota</button></td><td><span class="origin" :class="(record as ProductRecord).origin.toLowerCase()">{{ (record as ProductRecord).origin }}</span><small>{{ new Date((record as ProductRecord).updatedAt).toLocaleString('pt-BR') }}</small></td><td><button class="status-toggle" @click="toggle(record.id)">{{ record.status==='active'?'Ativo':'Inativo' }}</button></td></template>
            <template v-else-if="mode==='processes'"><td>{{ (record as ProcessRecord).sequence }}</td><td><strong>{{ (record as ProcessRecord).code }} · {{ (record as ProcessRecord).name }}</strong><small>{{ (record as ProcessRecord).status==='active'?'Ativo':'Inativo' }}</small></td><td>{{ (record as ProcessRecord).type||'—' }}</td><td>{{ customerNames((record as ProcessRecord).customerKeys) }}</td><td>{{ (record as ProcessRecord).resourceIds.length }}</td><td>{{ (record as ProcessRecord).layoutNodeId||'—' }}</td><td><strong>{{ (record as ProcessRecord).powerBiMeasure||'—' }}</strong><small>{{ (record as ProcessRecord).demandMeasure||'—' }} / {{ (record as ProcessRecord).productionMeasure||'—' }}</small></td><td><span class="validation" :class="(record as ProcessRecord).validation">{{ validationLabel((record as ProcessRecord).validation) }}</span></td></template>
            <template v-else-if="mode==='resources'"><td><strong>{{ (record as ResourceRecord).code }}</strong><small>{{ (record as ResourceRecord).name }}</small></td><td>{{ processes.find(p=>p.id===(record as ResourceRecord).processId)?.name||'—' }}</td><td><span class="data-state" :class="{ready:operational.ready}">{{ operational.ready?'MES observado':'Sem dado MES' }}</span><small>{{ operational.ready?'Valores do cache local somente leitura':'Nenhum valor operacional apresentado como observado' }}</small></td><td><strong>{{ fmt(measure(record as ResourceRecord,(record as ResourceRecord).productionMeasure)) }} / {{ fmt(measure(record as ResourceRecord,(record as ResourceRecord).demandMeasure)) }}</strong><small>Produção / demanda observada</small></td><td>{{ fmt(measure(record as ResourceRecord,(record as ResourceRecord).remainingMeasure)) }}</td><td>{{ fmt(measure(record as ResourceRecord,(record as ResourceRecord).programmedStopsMeasure)) }} / {{ fmt(measure(record as ResourceRecord,(record as ResourceRecord).downtimeMeasure)) }} min</td><td>{{ fmt((record as ResourceRecord).oeeTarget,1) }}%</td><td>{{ operational.updatedAt?new Date(operational.updatedAt).toLocaleString('pt-BR'):'—' }}</td><td><RouterLink class="capacity-link" to="/mifc/capacity">Editar parâmetros em Capacidade</RouterLink></td></template>
            <template v-else><td>{{ (record as MasterDataRecord).category }}</td><td><code>{{ (record as MasterDataRecord).key }}</code></td><td>{{ (record as MasterDataRecord).label }}</td><td><strong>{{ (record as MasterDataRecord).value }}</strong> {{ (record as MasterDataRecord).unit }}</td><td><span class="origin" :class="(record as MasterDataRecord).origin.toLowerCase()">{{ (record as MasterDataRecord).origin }}</span></td><td><button class="status-toggle" @click="toggle(record.id)">{{ record.status==='active'?'Ativo':'Inativo' }}</button></td><td>{{ new Date((record as MasterDataRecord).updatedAt).toLocaleString('pt-BR') }}</td></template>
            <td class="row-actions"><button title="Detalhes" @click="openDetails(record as unknown as Record<string,unknown>)"><Eye :size="15"/></button><button title="Editar" @click="openEditor(record as unknown as Record<string,unknown>)"><Pencil :size="15"/></button><button v-if="mode!=='master'" title="Duplicar" @click="duplicate(record.id)"><Copy :size="15"/></button><button :title="record.status==='active'?'Desativar':'Reativar'" :aria-label="`${record.status==='active'?'Desativar':'Reativar'} ${recordLabel(record as any)}`" :class="{ 'reactivate-icon': record.status === 'inactive' }" @click="toggle(record.id)"><Power :size="15"/></button></td>
          </tr>
        </tbody></table></div></section>
    </template>

    <div v-if="editorOpen||detailsOpen" class="dialog-backdrop" @click.self="editorOpen=false;detailsOpen=false"><section class="entity-dialog" role="dialog" aria-modal="true"><header><div><small>{{ detailsOpen?'CONSULTA':'EDIÇÃO LOCAL' }}</small><h2>{{ detailsOpen?'Detalhes do registro':editing.id&&records.some(r=>r.id===editing.id)?'Editar registro':'Novo registro' }}</h2></div><button @click="editorOpen=false;detailsOpen=false">×</button></header><div v-if="detailsOpen" class="details-grid"><div v-for="(value,key) in editing" :key="key"><small>{{ key }}</small><strong>{{ Array.isArray(value)?value.join(', ')||'—':String(value??'—') }}</strong></div></div><form v-else class="editor-form" @submit.prevent="save">
      <template v-if="mode==='products'"><label>Código<input v-model.trim="editing.code" required/></label><label>Descrição<input v-model.trim="editing.description" required/></label><label>Cliente<input v-model.trim="editing.customer"/></label><label>Família<input v-model.trim="editing.family"/></label><label>Classe<input v-model.trim="editing.productClass"/></label><label>Mão / lado<input v-model.trim="editing.hand"/></label><label>Comprimento (mm)<input v-model.number="editing.finishLength" type="number" min="0"/></label><label>Material / MP<input v-model.trim="editing.material"/></label><label class="wide">Rota de processos<select v-model="editing.routeProcessIds" multiple><option v-for="process in processes" :key="process.id" :value="process.id">{{ process.sequence }} · {{ process.name }}</option></select></label><p v-if="editing.origin==='ORACLE_MES'" class="wide source-warning">A edição cria somente um override local. O registro de origem no Oracle permanece intacto.</p></template>
      <template v-else-if="mode==='processes'"><label>Código<input v-model.trim="editing.code" required/></label><label>Nome<input v-model.trim="editing.name" required/></label><label>Sequência<input v-model.number="editing.sequence" type="number"/></label><label>Tipo<input v-model.trim="editing.type"/></label><label>Clientes<select v-model="editing.customerKeys" multiple><option value="FH">Volvo FH</option><option value="VM">Volvo VM</option><option value="SCA">Scania</option><option value="DAF">DAF</option></select></label><label>Produtos<select v-model="editing.productIds" multiple><option v-for="product in products" :key="product.id" :value="product.id">{{ product.code }}</option></select></label><label>Recursos<select v-model="editing.resourceIds" multiple><option v-for="resource in resources" :key="resource.id" :value="resource.id">{{ resource.name }}</option></select></label><label>Nó do Layout<input v-model.trim="editing.layoutNodeId"/></label><label>Medida Power BI<input v-model.trim="editing.powerBiMeasure"/></label><label>Medida demanda<input v-model.trim="editing.demandMeasure"/></label><label>Medida produção<input v-model.trim="editing.productionMeasure"/></label><label>Paridade<select v-model="editing.validation"><option value="mapped">Validado</option><option value="divergent">Divergente</option><option value="pending">Pendente</option></select></label><label class="wide">Observações<textarea v-model.trim="editing.notes" rows="3"></textarea></label></template>
      <template v-else-if="mode==='resources'"><label>Código<input v-model.trim="editing.code" required/></label><label>Nome<input v-model.trim="editing.name" required/></label><label>Processo<select v-model="editing.processId" required><option value="">Selecione</option><option v-for="process in processes" :key="process.id" :value="process.id">{{ process.name }}</option></select></label><label>Medida produção<input v-model.trim="editing.productionMeasure"/></label><label>Medida demanda<input v-model.trim="editing.demandMeasure"/></label><label>Medida restante<input v-model.trim="editing.remainingMeasure"/></label><label>Parada programada<input v-model.trim="editing.programmedStopsMeasure"/></label><label>Downtime<input v-model.trim="editing.downtimeMeasure"/></label><label>Status operacional<select v-model="editing.operationalStatus"><option value="unknown">Indisponível</option><option value="operational">Operacional</option><option value="attention">Atenção</option><option value="stopped">Parado</option></select></label><p class="wide source-warning">Horas, turnos, ciclo, disponibilidade e capacidade/dia são parâmetros de planejamento. Edite esses valores no módulo <RouterLink to="/mifc/capacity">Capacidade</RouterLink>.</p></template>
      <template v-else><label>Categoria<input v-model.trim="editing.category" required/></label><label>Chave<input v-model.trim="editing.key" required/></label><label>Nome<input v-model.trim="editing.label" required/></label><label>Valor<input v-model.trim="editing.value" required/></label><label>Unidade<input v-model.trim="editing.unit"/></label><label>Origem<select v-model="editing.origin"><option value="LOCAL">Manual local</option><option value="CALCULATED">Calculada</option><option value="ORACLE_MES">Oracle MES</option></select></label><label class="wide">Observações<textarea v-model.trim="editing.notes" rows="3"></textarea></label></template>
      <label>Status<select v-model="editing.status"><option value="active">Ativo</option><option value="inactive">Inativo</option></select></label><footer class="wide"><button type="button" class="button button-secondary" @click="editorOpen=false">Cancelar</button><button class="button button-primary" type="submit">Salvar localmente</button></footer>
    </form></section></div>
    <div v-if="routeProduct" class="dialog-backdrop" @click.self="routeProduct=null"><section class="entity-dialog route-dialog" role="dialog" aria-modal="true" aria-labelledby="route-title"><header><div><small>ROTA DO PRODUTO</small><h2 id="route-title">{{ routeProduct.code }} · {{ routeProduct.description }}</h2></div><button aria-label="Fechar rota" @click="routeProduct=null">×</button></header><ol v-if="routeProduct.routeProcessIds.length"><li v-for="processId in routeProduct.routeProcessIds" :key="processId"><span>{{ processes.find(process=>process.id===processId)?.sequence??'—' }}</span><strong>{{ processes.find(process=>process.id===processId)?.name??'Processo não localizado' }}</strong></li></ol><StatePanel v-else state="empty" title="Rota não informada" message="Este produto ainda não possui processos relacionados." /></section></div>
  </main>
</template>

<style scoped>
.registry-page{display:grid;gap:16px}.eyebrow{margin:0 0 5px!important;color:var(--brand-blue);font-size:10px!important;font-weight:700;letter-spacing:.08em}.context-banner{padding:12px 15px;border:1px solid #b9e5c8;border-radius:8px;background:#effaf3;color:#15713a;font-size:12px}.context-banner.danger{border-color:#f2b9b5;background:#fff3f2;color:#a42620}.filter-card{display:flex;align-items:center;gap:10px;padding:12px}.search-box{display:flex;min-width:280px;flex:1;align-items:center;gap:8px;padding:0 12px;border:1px solid var(--border-subtle);border-radius:7px}.search-box input{width:100%;height:36px;border:0;outline:0}.filter-card select{height:38px;padding:0 10px;border:1px solid var(--border-subtle);border-radius:7px;background:#fff}.filter-card>span{color:var(--text-tertiary);font-size:11px}.parity-legend{display:flex;align-items:center;gap:8px}.parity-legend small{color:var(--text-tertiary)}.table-card{overflow:hidden}.table-scroll{overflow-x:auto}.data-table{min-width:1040px}.data-table td{vertical-align:top}.data-table td strong,.data-table td small{display:block}.data-table td small{margin-top:4px;color:var(--text-tertiary);font-size:10px}.route-cell{min-width:105px;white-space:nowrap}.route-button,.capacity-link{display:inline-flex;margin-top:5px;border:0;background:transparent;color:var(--brand-blue);font-size:10px;font-weight:700;text-decoration:none;cursor:pointer}.origin,.validation,.status-toggle,.data-state{display:inline-flex;padding:4px 7px;border:0;border-radius:999px;background:#edf3ff;color:#205bd8;font-size:9px;font-weight:700}.origin.oracle_mes,.validation.mapped,.data-state.ready{background:#e9f8ef;color:#157a3c}.origin.calculated,.validation.divergent{background:#fff0ef;color:#a42620}.validation.pending,.data-state{background:#fff3db;color:#a35c00}.status-toggle{background:#eaf8ef;color:#137438;cursor:pointer}.row-actions{white-space:nowrap}.row-actions button{display:inline-grid;width:28px;height:28px;place-items:center;border:0;border-radius:5px;background:transparent;color:var(--text-secondary)}.row-actions button:hover{background:var(--surface-selected);color:var(--brand-blue)}.row-actions .danger-icon:hover{background:#fff0ef;color:var(--danger)}.compact .data-table td{padding-top:7px;padding-bottom:7px}.dialog-backdrop{position:fixed;z-index:120;inset:0;display:grid;place-items:center;padding:20px;background:rgba(15,29,52,.42)}.entity-dialog{display:flex;width:min(900px,96vw);max-height:90vh;flex-direction:column;overflow:hidden;border-radius:12px;background:#fff;box-shadow:0 22px 70px rgba(0,0,0,.25)}.entity-dialog>header{display:flex;align-items:center;justify-content:space-between;padding:17px 20px;border-bottom:1px solid var(--border-subtle)}.entity-dialog h2{margin:3px 0 0;font-size:18px}.entity-dialog header small{color:var(--brand-blue);font-weight:700}.entity-dialog header button{border:0;background:transparent;font-size:26px}.editor-form,.details-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;overflow:auto;padding:20px}.editor-form label{display:grid;gap:6px;color:var(--text-secondary);font-size:11px;font-weight:600}.editor-form input,.editor-form select,.editor-form textarea{min-height:38px;padding:8px;border:1px solid var(--border-subtle);border-radius:6px;background:#fff;font:inherit}.editor-form select[multiple]{min-height:105px}.wide{grid-column:1/-1}.editor-form footer{display:flex;justify-content:flex-end;gap:8px;padding-top:8px}.source-warning{margin:0;padding:10px;border-radius:7px;background:#fff6e7;color:#8c5700;font-size:11px}.details-grid div{padding:10px;border:1px solid var(--border-subtle);border-radius:7px}.details-grid small,.details-grid strong{display:block;overflow-wrap:anywhere}.details-grid small{margin-bottom:5px;color:var(--text-tertiary);text-transform:uppercase}.details-grid strong{font-size:12px}.route-dialog{width:min(580px,96vw)}.route-dialog ol{display:grid;gap:8px;margin:0;padding:20px;overflow:auto;list-style:none}.route-dial